inline constexpr std::size_t RuneCount() {
    return kRunes.size();
}

inline constexpr std::size_t StyleCount() {
    return kStyles.size();
}

inline const RuneDataEntry* FindById(int id) {
    std::size_t lo = 0;
    std::size_t hi = kRunes.size();
    while (lo < hi) {
        const std::size_t mid = lo + ((hi - lo) / 2);
        if (kRunes[mid].Id < id) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo < kRunes.size() && kRunes[lo].Id == id ? &kRunes[lo] : nullptr;
}

inline const RuneStyleDataEntry* FindStyleById(int id) {
    std::size_t lo = 0;
    std::size_t hi = kStyles.size();
    while (lo < hi) {
        const std::size_t mid = lo + ((hi - lo) / 2);
        if (kStyles[mid].Id < id) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    return lo < kStyles.size() && kStyles[lo].Id == id ? &kStyles[lo] : nullptr;
}

